<script setup lang="ts">
import { computed } from 'vue'
import LogoTile from './LogoTile.vue'

/**
 * The InvoiceShelf lockup: the mark in its tile, then the wordmark.
 *
 * The wordmark is Geologica at weight 600, outlined, so it never waits for the
 * web font and takes its colour from the surrounding text colour (a
 * text-heading class, say). `lightColor` still sets it directly for callers
 * that pass one; `darkColor` is kept for compatibility and unused.
 */
interface Props {
  darkColor?: string
  lightColor?: string
}

const props = withDefaults(defineProps<Props>(), {
  darkColor: undefined,
  lightColor: undefined,
})

const style = computed(() => (props.lightColor ? { color: props.lightColor } : undefined))
</script>

